import {Game,WORDS,CHAPTERS,PATH,PADS,LENGTH,position} from './engine.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const SAVE='wordward-save-v1',RECORD='wordward-record-v1';
let game=new Game(),records=[0,0,0],paused=false,speed=1,chars=['火','球'],placing=null,selected=null,hover=-1,audioOn=false,audioCtx,toastTimer,stored=false;
try{const raw=JSON.parse(localStorage.getItem(RECORD));if(Array.isArray(raw)&&raw.length===3&&raw.every(n=>Number.isInteger(n)&&n>=0&&n<=3))records=raw;const saved=localStorage.getItem(SAVE);if(saved){const candidate=Game.restore(JSON.parse(saved));if(!['won','lost'].includes(candidate.phase)){game=candidate;paused=game.phase==='battle';stored=true;}}}catch{try{localStorage.removeItem(SAVE)}catch{}}
const forgeTemplate=$('.forge-panel').innerHTML;
const mobileLayout=matchMedia('(max-width: 900px)');
function revealPanel(selector){if(mobileLayout.matches)$(selector).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
$('#jump-battle').onclick=()=>revealPanel('#battle-panel');
