const c=$('#battlefield'),ctx=c.getContext('2d');c.removeAttribute('tabindex');c.setAttribute('role','img');
const mapTargets=document.createElement('div');mapTargets.className='map-targets';mapTargets.setAttribute('aria-label','阵位');$('#canvas-wrap').append(mapTargets);
PADS.forEach((p,i)=>{const b=document.createElement('button');b.className='map-target';b.style.left=`${p.x/9}%`;b.style.top=`${p.y/5.2}%`;b.setAttribute('aria-label',`空阵位 ${i+1}，点击放置词塔`);b.onclick=()=>selectPad(i);b.onmouseenter=()=>hover=i;b.onmouseleave=()=>hover=-1;b.onfocus=()=>hover=i;b.onblur=()=>hover=-1;mapTargets.append(b);});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(game.export()));localStorage.setItem(RECORD,JSON.stringify(records));$('#save-status').textContent='✓ 进度自动保存';}catch{$('#save-status').textContent='此浏览器无法保存进度';}}
function sound(note=440,duration=.09){if(!audioOn)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=note;g.gain.setValueAtTime(.045,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function recipe(){return chars.length===2?WORDS.find(w=>[...w.word].sort().join('')===[...chars].sort().join('')):null;}
function renderForge(){const panel=$('.forge-panel');panel.classList.toggle('inspecting',selected!==null);$('#forge-shortcut-label').textContent=selected!==null?'词塔详情':'组字建塔';const t=game.towers.find(t=>t.id===selected);if(selected!==null&&!t)selected=null;
 if(t){const w=WORDS.find(w=>w.word===t.word),damage=Math.round(w.damage*(1+(t.level-1)*.65));panel.innerHTML=`<div class="forge-heading"><span>词塔详情</span><button id="back-forge" aria-label="返回组字工坊">返回 ↗</button></div><div class="tower-detail"><h3>${w.word}</h3><div class="tower-level">${'◆'.repeat(t.level)}${'◇'.repeat(3-t.level)}</div><p>${w.desc}</p><div class="detail-stats"><div><small>攻击伤害</small><b>${damage||'+35%'}</b></div><div><small>攻击范围</small><b>${w.range+(t.level-1)*15}</b></div><div><small>攻击间隔</small><b>${w.type==='aura'?'—':(w.rate/(1+(t.level-1)*.14)).toFixed(2)+'s'}</b></div><div><small>当前等级</small><b>${t.level} / 3</b></div></div><div class="tower-actions"><button id="upgrade" class="forge-button">${t.level===3?'已臻化境':'淬炼升级'}<span>${t.level===3?'最高等级':game.upgradeCost(t)+' 墨点 ↗'}</span></button><button id="sell" class="sell-button">拆除词塔 · 返还 70% 墨点</button></div></div><div class="forge-footnote">弯道交汇处，往往是最好的阵位。</div>`;$('#back-forge').onclick=()=>{selected=null;renderForge()};$('#upgrade').disabled=t.level>=3||game.ink<game.upgradeCost(t)||['won','lost'].includes(game.phase);$('#upgrade').onclick=()=>{if(game.upgrade(t.id)){sound(660);toast('词塔淬炼成功');save();renderForge();updateUI()}};$('#sell').onclick=()=>{game.sell(t.id);selected=null;renderForge();save();updateUI();toast('词塔已拆除，墨点已返还')};return;}
 panel.innerHTML=forgeTemplate;
 $('#forge-slots').innerHTML=`<div class="forge-slot ${chars[0]?'':'empty'}">${chars[0]||'字'}</div><span class="forge-plus">+</span><div class="forge-slot ${chars[1]?'':'empty'}">${chars[1]||'字'}</div>`;
 $('#character-grid').innerHTML=[...'火球冰霜雷电风刃巨石光环'].map(ch=>`<button class="char ${chars.includes(ch)?'selected':''}" data-char="${ch}" aria-pressed="${chars.includes(ch)}" aria-label="选择汉字${ch}">${ch}</button>`).join('');
 $$('.char').forEach(b=>b.onclick=()=>{placing=null;const ch=b.dataset.char;if(chars.includes(ch))chars=chars.filter(x=>x!==ch);else if(chars.length<2)chars.push(ch);else chars=[chars[1],ch];sound(390+chars.length*100);renderForge();updateUI()});
 const w=recipe();$('#recipe-preview').innerHTML=w?`<div class="recipe-title">${w.word}<span class="recipe-tag">${w.tag}</span></div><p>${w.desc}</p><div class="recipe-stats"><span><small>${w.damage?'伤害':'增益'}</small>${w.damage||'35%'}</span><span><small>范围</small>${w.range}</span><span><small>间隔</small>${w.type==='aura'?'—':w.rate+'s'}</span></div>`:`<div class="invalid-recipe">${chars.length<2?'落下两字，静候成词。':'此二字尚未成阵。'}</div><p>试试 火 + 球、冰 + 霜、雷 + 电、风 + 刃、巨 + 石、光 + 环。</p>`;
 $('#forge').innerHTML=placing?'取消放置 <span>返回选字 ↩</span>':`凝字成塔 <span>${w?w.cost+' 墨点 ↗':'待成词'}</span>`;$('#forge').disabled=!w||game.ink<w.cost||['won','lost'].includes(game.phase);$('#forge').onclick=()=>{if(placing){placing=null;renderForge();updateUI();return;}placing=w.word;selected=null;toast('请选择山道旁的圆形空阵位');sound(600);renderForge();updateUI();revealPanel('#battle-panel')};$('#clear-chars').onclick=()=>{chars=[];placing=null;renderForge();updateUI()};}
function selectPad(i){if($('#modal').open||['won','lost'].includes(game.phase))return;const tower=game.towers.find(t=>t.pad===i);if(tower){selected=tower.id;placing=null;renderForge();sound(460);revealPanel('#forge-panel');}else if(placing){if(game.build(placing,i)){placing=null;selected=null;renderForge();save();sound(700);toast('词塔已落成，蓄势待发')}else toast('墨点不足，暂时无法建塔');}else{selected=null;renderForge();toast('先在组字工坊组词，再点击「凝字成塔」');}updateUI();}
function updateUI(){const ch=CHAPTERS[game.chapter],terminal=['won','lost'].includes(game.phase);$('#chapter-name').textContent=ch.name;$('.chapter-mark').textContent=['壹','贰','叁'][game.chapter];$('#area-name').textContent=ch.area;$('#chapter-intro').textContent=ch.intro;$('#wave-total').textContent=ch.waves;$('.map-label span').textContent=ch.area;$('.map-label small').textContent=['QINGSHAN TRAIL','BAMBOO VALLEY','THE LAST ARCHIVE'][game.chapter];$('#hp').textContent=game.hp;$('#max-hp').textContent='/ '+ch.hp;$('#ink').textContent=Math.floor(game.ink);$('#phase-label').textContent=terminal?(game.phase==='won'?'山河无恙':'山门失守'):paused?'暂歇片刻':game.phase==='battle'?'守关进行中':'布阵时刻';$('#wave-label').textContent=game.phase==='prepare'?`第 ${game.wave+1} 波将至`:`第 ${game.wave} / ${ch.waves} 波`;const done=game.phase==='prepare'||game.phase==='won'?game.wave:Math.max(0,game.wave-1);$('#progress-label').textContent=`${done} / ${ch.waves}`;$('#wave-dots').innerHTML=Array.from({length:ch.waves},(_,i)=>`<i class="${i<done?'done':''}"></i>`).join('');$('#wave-title').textContent=terminal?(game.phase==='won'?'此卷已守 · 山河无恙':'山门失守 · 来日再战'):game.phase==='battle'?`第 ${game.wave} 波 · ${game.wave%3===0?'墨魁压境':'墨影来袭'}`:`第 ${game.wave+1} 波 · ${(game.wave+1)%3===0?'墨魁将至':'蓄势待发'}`;$('#wave-description').textContent=game.phase==='battle'?`场上 ${game.enemies.length} 只 · 待出现 ${game.queue.length} 只`:(game.wave===0?'准备好你的第一座词塔':terminal?'每一次落字，皆是修行':'波次已清，补强防线后再出发');$('#start').innerHTML=terminal?'查看战报 ↗':game.phase==='battle'?(paused?'继续守关 ▷':'暂歇片刻 Ⅱ'):'迎战墨影 <span>→</span>';$('#pause-overlay').classList.toggle('hidden',!paused||terminal);$('#map-message').textContent=placing?'落字成阵 · 点击圆形空阵位建塔':selected?'在词塔详情中升级，或拆除词塔':terminal?(game.phase==='won'?'山河无恙 · 此卷已守':'山门失守 · 再试一阵'):game.phase==='battle'?'战斗中也可建塔、升级，随时调整防线':game.towers.length?'布阵就绪，点击「迎战墨影」开始下一波':'点击「凝字成塔」，开始布阵';$('#speed').textContent=speed+'×';const cooldown=Math.ceil(Math.max(0,game.skillReady-game.time));$('#skill').disabled=game.phase!=='battle'||cooldown>0||game.ink<30||paused;$('#skill').innerHTML=`✦ <span>${cooldown?cooldown+'s':'落墨'}</span><small>${cooldown?'':'30'}</small>`;$('#skill').setAttribute('aria-label',cooldown?`落墨技能冷却中，还需${cooldown}秒`:'落墨技能：花费30墨点，全场100伤害');[...mapTargets.children].forEach((b,i)=>{const t=game.towers.find(t=>t.pad===i);b.setAttribute('aria-label',t?`阵位${i+1}：${t.word}，${t.level}级，点击查看或升级`:`空阵位${i+1}，点击放置词塔`);});if($('#upgrade')){const t=game.towers.find(t=>t.id===selected);$('#upgrade').disabled=!t||t.level>=3||game.ink<game.upgradeCost(t)||terminal;}if($('#forge')){const w=recipe();$('#forge').disabled=!w||game.ink<w.cost||terminal;}}
function reset(ch=game.chapter){game=new Game(ch);paused=false;placing=null;selected=null;chars=['火','球'];speed=1;renderForge();updateUI();save();}
function openModal(html,setup){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();setup?.();}
function closeModal(){$('#modal').close();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav==='campaign'));}
$('#close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#modal').addEventListener('close',()=>{$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav==='campaign'))});
function codex(){openModal(`<div class="modal-eyebrow">THE WORD CODEX</div><h2 class="modal-title">万字有灵，各有所长。</h2><p class="modal-intro">六座词塔，六种守护。合理搭配，比一味叠加更有力量。</p><div class="codex-grid">${WORDS.map(w=>`<article class="codex-card"><h3 style="color:${w.color}">${w.word}<small>${w.tag} · ${w.cost} 墨点</small></h3><p>${w.desc}</p><div class="recipe-stats"><span>伤害 ${w.damage||'增益35%'}</span><span>范围 ${w.range}</span></div></article>`).join('')}</div>`);}
function guide(){openModal(`<div class="modal-eyebrow">A LITTLE FIELD GUIDE</div><h2 class="modal-title">一字起，万象生。</h2><p class="modal-intro">一场组词与策略的山河之旅。没有时间催促你，布好阵，再迎战。</p><div class="guide-step"><span>01</span><div><h3>选字成词</h3><p>在组字工坊中点选两个汉字，例如「火」和「球」。字序不限；已选的字再次点击可取消。</p></div></div><div class="guide-step"><span>02</span><div><h3>落字成阵</h3><p>点击「凝字成塔」，再点击山道旁的圆形阵位。建造消耗墨点，击败墨影和完成波次可获得更多墨点。</p></div></div><div class="guide-step"><span>03</span><div><h3>借势守关</h3><p>「冰霜」延缓墨影，「火球」清理群体，「巨石」克制护甲。「光环」提高附近词塔伤害，同类光环不叠加。点击词塔可以升级至三级，或拆除返还 70% 投入。</p></div></div><div class="guide-step"><span>04</span><div><h3>迎战墨影</h3><p>点击「迎战墨影」开始一波。战斗中可继续建塔、升级；「落墨」消耗 30 墨点，造成全场 100 伤害，冷却 28 秒。每第三波出现墨魁，漏过山门会损失 4 点生命。</p></div></div><p class="modal-intro">通关评星：剩余生命 ≥ 80% 为三星，≥ 40% 为二星，其余为一星。三个篇章均可自由挑战。进度保存在当前浏览器，刷新后可继续；切换篇章会替换当前战局。</p><button class="primary" id="guide-done">落笔，启程 →</button>`,()=>$('#guide-done').onclick=closeModal);}
function chapters(){openModal(`<div class="modal-eyebrow">THE CAMPAIGN</div><h2 class="modal-title">山河有字，等你守护。</h2><p class="modal-intro">选择一个篇章，开启新的守关。切换篇章会替换当前战局，通关星级将保留。</p>${CHAPTERS.map((ch,i)=>`<button class="chapter-card" data-chapter="${i}"><span>${['壹','贰','叁'][i]}</span><div><h3>${ch.name}</h3><small>${ch.waves} 波墨影 · ${ch.hp} 点生命 · ${ch.ink} 初始墨点</small></div><div class="chapter-stars" aria-label="${records[i]}星">${'★'.repeat(records[i])}${'☆'.repeat(3-records[i])}</div></button>`).join('')}`,()=>$$('[data-chapter]').forEach(b=>b.onclick=()=>{const ch=+b.dataset.chapter;if(game.wave||game.towers.length){openModal(`<div class="modal-eyebrow">A NEW CHAPTER</div><h2 class="modal-title">启程前往${CHAPTERS[ch].name}？</h2><p class="modal-intro">当前战局将被替换，已获得的通关星级会保留。</p><div class="result-actions"><button class="secondary" id="stay">继续当前战局</button><button class="primary" id="switch-chapter">开启新篇章 →</button></div>`,()=>{$('#stay').onclick=closeModal;$('#switch-chapter').onclick=()=>{reset(ch);closeModal();}})}else{reset(ch);closeModal();}}));}
function result(){const won=game.phase==='won',stars=won?(game.hp/CHAPTERS[game.chapter].hp>=.8?3:game.hp/CHAPTERS[game.chapter].hp>=.4?2:1):0;if(won){records[game.chapter]=Math.max(records[game.chapter],stars);save();}openModal(`<div class="result"><div class="modal-eyebrow">${won?'CHAPTER COMPLETE':'EVERY WORD, ANOTHER TRY'}</div><div class="result-seal">${won?'守':'再'}</div><h2 class="modal-title">${won?'此卷已守，山河无恙。':'落字未尽，来日再战。'}</h2><p class="modal-intro">${won?'你用文字的力量，留住了一方安宁。':'试着在弯道布下冰霜，配合火球清理成群墨影。'}</p><div class="result-stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><div class="result-stats"><div><b>${game.kills}</b><small>击退墨影</small></div><div><b>${game.hp}</b><small>剩余生命</small></div><div><b>${game.wave}</b><small>抵御波次</small></div></div><div class="result-actions"><button class="secondary" id="retry">再守此卷</button><button class="primary" id="next">${won&&game.chapter<2?'开启下一篇章 →':'翻开山河卷 →'}</button></div></div>`,()=>{$('#retry').onclick=()=>{reset();closeModal()};$('#next').onclick=()=>{if(won&&game.chapter<2){reset(game.chapter+1);closeModal()}else chapters()};});}
function settings(){openModal(`<div class="modal-eyebrow">A QUIETER MOMENT</div><h2 class="modal-title">案头小设</h2><div class="setting-row"><div>落字音效<p>简单的琴音，陪伴每次落字。</p></div><button id="sound-setting">${audioOn?'已开启':'已关闭'}</button></div><div class="setting-row"><div>重开当前篇章<p>重置当前布阵，保留已获得的通关星级。</p></div><button id="restart-setting">重新开始</button></div><div class="setting-row"><div>本地存档<p>战局与星级仅保存在此浏览器，无需注册。</p></div><button id="erase-setting" class="danger">清除全部进度</button></div><p class="modal-intro">字阵 v1.0 · 三章战役 / 六种词塔<br>快捷键：空格迎战或暂停，Esc 取消选中。切换到其他页面会自动暂停。</p>`,()=>{$('#sound-setting').onclick=()=>{toggleSound();$('#sound-setting').textContent=audioOn?'已开启':'已关闭'};$('#restart-setting').onclick=()=>confirmReset(false);$('#erase-setting').onclick=()=>confirmReset(true);});}
function confirmReset(all){openModal(`<div class="modal-eyebrow">START AFRESH</div><h2 class="modal-title">${all?'清除全部进度？':'重新开始此卷？'}</h2><p class="modal-intro">${all?'当前战局与所有篇章星级将被清除。此操作无法撤销。':'当前阵容和波次将重置，已有通关星级会保留。'}</p><div class="result-actions"><button class="secondary" id="cancel-reset">保留进度</button><button class="primary" id="do-reset">确认${all?'清除':'重开'}</button></div>`,()=>{$('#cancel-reset').onclick=settings;$('#do-reset').onclick=()=>{if(all)records=[0,0,0];reset(all?0:game.chapter);closeModal();toast(all?'已清除进度，山河重启':'新的一卷，落笔启程')};});}
function toggleSound(){audioOn=!audioOn;$('.sound-off').classList.toggle('hidden',audioOn);$('#sound').setAttribute('aria-label',audioOn?'关闭音效':'开启音效');$('#sound').title=audioOn?'关闭音效':'开启音效';sound(520,.16);}
$('#sound').onclick=toggleSound;$('#settings').onclick=settings;$('#mobile-settings').onclick=settings;$('#guide-link').onclick=guide;$('#chapters').onclick=chapters;$$('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='codex')codex();else if(b.dataset.nav==='guide')guide();else{closeModal();return;}$$('.nav-item').forEach(x=>x.classList.toggle('active',x===b));});
function start(){if(['won','lost'].includes(game.phase))return result();if(game.phase==='prepare'){if(!game.towers.length){toast('先建造至少一座词塔，再迎战墨影');return;}game.startWave();paused=false;sound(320,.2);save();}else{paused=!paused;save();}updateUI();}
$('#start').onclick=start;$('#resume').onclick=()=>{paused=false;updateUI()};$('#speed').onclick=()=>{speed=speed===1?2:speed===2?3:1;updateUI()};$('#skill').onclick=()=>{if(!paused&&game.skill()){sound(180,.4);toast('落墨如雨，荡尽墨影');save();updateUI();}};
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.code==='Space'&&!['BUTTON','INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();start();}if(e.key==='Escape'){placing=null;selected=null;renderForge();updateUI();}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.phase==='battle'){paused=true;save();updateUI();}});window.addEventListener('pagehide',save);
// All battle art is drawn locally; the game has no remote asset dependency.
let W=900,H=520,dpr=1;function resize(){const r=c.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);W=c.width;H=c.height;}new ResizeObserver(resize).observe(c);
function line(points,stroke,width){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();}
function circle(x,y,r,fill,stroke){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function mountain(x,y,w,h,alpha){ctx.fillStyle=`rgba(126,149,111,${alpha})`;ctx.beginPath();ctx.moveTo(x-w/2,y);ctx.bezierCurveTo(x-w*.3,y-h*.18,x-w*.1,y-h,x,y-h);ctx.bezierCurveTo(x+w*.15,y-h,x+w*.25,y-h*.25,x+w/2,y);ctx.fill();}
const scenery=Array.from({length:63},(_,i)=>({x:(i*137+51)%900,y:(i*83+17)%520,r:3+(i*17)%6})).filter(p=>!PATH.slice(1).some((b,i)=>{const a=PATH[i];return p.x>=Math.min(a.x,b.x)-43&&p.x<=Math.max(a.x,b.x)+43&&p.y>=Math.min(a.y,b.y)-43&&p.y<=Math.max(a.y,b.y)+43})&&!PADS.some(t=>Math.hypot(t.x-p.x,t.y-p.y)<41));
function draw(time){ctx.setTransform(W/900,0,0,H/520,0,0);ctx.clearRect(0,0,900,520);ctx.fillStyle=game.chapter===2?'#dfe6d8':'#e9eddf';ctx.fillRect(0,0,900,520);mountain(20,520,370,160,.1);mountain(790,110,340,160,.085);mountain(520,550,330,120,.1);mountain(500,36,190,75,.06);
 // very fine contours and wind lines
 ctx.strokeStyle='#a7b79b29';ctx.lineWidth=1;for(let i=0;i<4;i++){ctx.beginPath();ctx.ellipse(10,500,190+i*22,100+i*13,-.25,Math.PI,Math.PI*2);ctx.stroke();}for(const p of scenery){circle(p.x,p.y,p.r,'#a8ba9544');circle(p.x+4,p.y-3,p.r*.7,'#9bae8744');ctx.fillStyle='#9cab8755';ctx.fillRect(p.x-1,p.y,1,7);}
 // path, paper edge, center speckles
 line(PATH,'#cad1b9',48);line(PATH,'#f7f4e5',43);line(PATH,'#e4dfc8',33);line(PATH,'#ebe5d0',28);ctx.setLineDash([2,13]);line(PATH,'#d1c9ae',1);ctx.setLineDash([]);
 // entry marker and quiet stones
 ctx.save();ctx.translate(34,145);ctx.rotate(-.12);ctx.fillStyle='#8f947d';ctx.fillRect(-6,-43,12,25);ctx.fillStyle='#eae8d7';ctx.font='11px serif';ctx.textAlign='center';ctx.fillText('入',0,-27);ctx.restore();
 for(const p of [{x:59,y:188},{x:150,y:390},{x:466,y:60},{x:740,y:121},{x:857,y:415}]){ctx.fillStyle='#bdc5ad';ctx.beginPath();ctx.ellipse(p.x,p.y,9,5,.4,0,7);ctx.fill();ctx.beginPath();ctx.ellipse(p.x+12,p.y+4,5,3,-.3,0,7);ctx.fill();}
 // mountain gate at end of trail
 ctx.save();ctx.translate(865,370);ctx.fillStyle='#a4b295';ctx.fillRect(-20,-28,5,50);ctx.fillRect(15,-28,5,50);ctx.fillStyle='#6e8767';ctx.fillRect(-26,-36,52,8);ctx.fillRect(-22,-18,44,5);ctx.beginPath();ctx.moveTo(-34,-35);ctx.quadraticCurveTo(0,-48,34,-35);ctx.lineTo(26,-29);ctx.lineTo(-26,-29);ctx.fill();ctx.fillStyle='#e9e9d6';ctx.fillRect(-9,-29,18,15);ctx.font='9px serif';ctx.textAlign='center';ctx.fillStyle='#68815e';ctx.fillText('山门',0,-18);ctx.restore();
 for(let i=0;i<PADS.length;i++){const p=PADS[i],t=game.towers.find(t=>t.pad===i),highlight=hover===i;if(t)continue;circle(p.x,p.y+4,26,'#bdc9ab33');circle(p.x,p.y,23,placing?'#f7f4df':'#eef0e1','#bbc7a8');circle(p.x,p.y,18,null,placing?'#8b9d75':'#d4dcc7');ctx.strokeStyle=placing?'#8a9b70':'#b5c1a3';ctx.lineWidth=1;line([{x:p.x-5,y:p.y},{x:p.x+5,y:p.y}],ctx.strokeStyle,1);line([{x:p.x,y:p.y-5},{x:p.x,y:p.y+5}],ctx.strokeStyle,1);if(placing||highlight){ctx.setLineDash([3,5]);circle(p.x,p.y,30+(placing?Math.sin(time*.002)*1.5:0),null,'#92a47b');ctx.setLineDash([]);}}
 const sel=game.towers.find(t=>t.id===selected);if(sel){const w=WORDS.find(w=>w.word===sel.word),p=PADS[sel.pad];circle(p.x,p.y,w.range+(sel.level-1)*15,w.color+'0e',w.color+'65');}
 for(const t of game.towers){const p=PADS[t.pad],w=WORDS.find(w=>w.word===t.word);if(w.type==='aura'){ctx.setLineDash([4,12]);circle(p.x,p.y,38+Math.sin(time*.001)*2,null,'#bea96766');ctx.setLineDash([]);}ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#7e8f6a33';ctx.beginPath();ctx.ellipse(3,24,31,11,0,0,7);ctx.fill();ctx.fillStyle='#b6c0a1';ctx.fillRect(-23,16,46,6);ctx.fillStyle='#d9debf';ctx.fillRect(-19,10,38,9);ctx.fillStyle='#f9f4e4';ctx.strokeStyle=w.color;ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(-22,-29,44,47,4);ctx.fill();ctx.stroke();ctx.strokeStyle=w.color+'66';ctx.lineWidth=.7;ctx.strokeRect(-18,-25,36,39);ctx.fillStyle=w.color;ctx.font='26px "Noto Serif SC", "Songti SC", serif';ctx.textAlign='center';ctx.fillText(w.icon,0,4);ctx.fillStyle=w.color;ctx.fillRect(-26,-33,52,5);for(let j=0;j<t.level;j++)circle((j-(t.level-1)/2)*7,27,2.2,w.color);if(selected===t.id||hover===t.pad){ctx.strokeStyle='#7d9065';ctx.lineWidth=1;ctx.strokeRect(-29,-39,58,75)}ctx.restore();}
 for(const e of game.enemies){const p=position(e.d),bob=Math.sin(time*.009+e.id)*2;ctx.save();ctx.translate(p.x,p.y+bob);const boss=e.kind==='boss',r=boss?19:e.kind==='armor'?14:11;circle(2,r*.8,r*.9,'#44534122');ctx.fillStyle=e.slowUntil>game.time?'#64838b':boss?'#574f49':e.kind==='armor'?'#6f7161':'#48534a';ctx.beginPath();ctx.moveTo(-r,r*.6);ctx.bezierCurveTo(-r*1.3,-r,-r*.4,-r*1.4,0,-r);ctx.bezierCurveTo(r,-r*1.3,r*1.3,0,r,r*.7);ctx.lineTo(r*.3,r*.4);ctx.lineTo(0,r*.8);ctx.lineTo(-r*.4,r*.45);ctx.fill();ctx.fillStyle='#ecebd4';ctx.fillRect(-5,-3,2,3);ctx.fillRect(3,-3,2,3);if(e.kind==='armor'){ctx.strokeStyle='#b7b69a';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,-2,9,Math.PI,0);ctx.stroke();}if(e.kind==='swift'){line([{x:-r-8,y:1},{x:-r-3,y:1}],'#8a967e',1);line([{x:-r-11,y:5},{x:-r-4,y:5}],'#a2ac95',1);}if(boss){ctx.fillStyle='#b38e5e';ctx.font='13px serif';ctx.textAlign='center';ctx.fillText('魁',0,12);}if(e.hp<e.maxHp){ctx.fillStyle='#a8b099';ctx.fillRect(-16,-r-10,32,3);ctx.fillStyle=boss?'#aa7252':'#768c68';ctx.fillRect(-16,-r-10,32*Math.max(0,e.hp/e.maxHp),3);}ctx.restore();}
 for(const f of game.effects){const a=f.life/f.max;ctx.globalAlpha=a;if(f.kind==='bolt'){line([f.from,f.to],f.color,2.5);circle(f.to.x,f.to.y,4,f.color);}else if(f.kind==='blast')circle(f.to.x,f.to.y,60*(1-a),f.color+'15',f.color);else if(f.kind==='pop'){for(let i=0;i<5;i++){const angle=i*1.257;circle(f.to.x+Math.cos(angle)*(1-a)*24,f.to.y+Math.sin(angle)*(1-a)*24,2,f.color)}}else if(f.kind==='rain'){ctx.fillStyle='#f6f0d155';ctx.fillRect(0,0,900,520);for(let i=0;i<24;i++)line([{x:i*43,y:(i*67+(1-a)*460)%520-70},{x:i*43-25,y:(i*67+(1-a)*460)%520}],'#9c8050',2);}ctx.globalAlpha=1;}
}
let last=0,lastUI=0,lastSave=0;function frame(now){const dt=last?Math.min((now-last)/1000,.1):0;last=now;if(!paused&&!$('#modal').open){for(let i=0;i<speed;i++)game.step(dt);}if(game.events.length){const events=game.events.splice(0);for(const e of events){if(e.type==='clear'){toast(`第 ${game.wave} 波已清 · 获得 ${40+game.wave*6} 墨点`);sound(780,.25);save();renderForge();}if(e.type==='leak')sound(150,.14);if(e.type==='won'||e.type==='lost'){placing=null;selected=null;renderForge();save();result();}}}if(now-lastUI>180){updateUI();lastUI=now;}if(now-lastSave>5000){save();lastSave=now;}draw(now);requestAnimationFrame(frame);}
renderForge();updateUI();resize();save();requestAnimationFrame(frame);if(stored)setTimeout(()=>toast(paused?'已恢复战局，点击「继续守关」接着玩':'已恢复上次布阵，落字再战'),500);
